<?php

namespace App\Support;

use App\Actions\Results\HttpBenchmarkResults;
use App\Support\Http\LoadStep;

/**
 * Renders the shell scripts an external load generator runs. Both are
 * generated by the target server — the bootstrap from the pairing session,
 * the work batches from HttpBenchCommand at the moment the run's HTTP stage
 * arms — so the load a second machine drives is exactly the standard load a
 * self-test would run, by construction.
 */
class GeneratorScript
{
    /** Pins every window to one address; see LoadProfile::connectTo(). */
    protected ?string $connectTo = null;

    /**
     * The script behind `curl … | sh`: preflights oha and reachability,
     * measures the round trip, handshakes, then polls for work.
     *
     * @param  array<string, mixed>  $session
     */
    public function bootstrap(array $session): string
    {
        return view('bench.generator-script', [
            'base' => escapeshellarg($session['base_url']),
            'target' => escapeshellarg($session['target_url']),
            'token' => escapeshellarg($session['token']),
            'curlInsecure' => $this->curlInsecure($session),
        ])->render();
    }

    /**
     * A batch of work the bootstrap fetches once the stage arms.
     *
     * A run is handed two of these. The first is the sweep; the second is the
     * response-time pass, which cannot be written down until the sweep has
     * landed, because the rate it offers is a fraction of what the sweep
     * proved the server can hold. The generator loops back to the same poll
     * for the second batch, so nothing about its protocol changes.
     *
     * Every step is rendered by HttpBenchCommand, the same class the local
     * self-test renders from, so the load cannot drift between the two.
     *
     * @param  array<int, LoadStep>  $steps
     * @param  array<string, mixed>  $session
     */
    public function work(array $steps, bool $insecure, array $session, ?string $connectTo = null): string
    {
        $command = new HttpBenchCommand;
        $this->connectTo = $connectTo;

        return view('bench.generator-work', [
            'base' => escapeshellarg($session['base_url']),
            'token' => escapeshellarg($session['token']),
            'curlInsecure' => $this->curlInsecure($session),
            'measured' => count(array_filter($steps, fn (LoadStep $step): bool => $step->isMeasured())),
            'steps' => $this->numbered($steps, $command, $insecure),
        ])->render();
    }

    /**
     * Each step with its position among the measured ones, so the terminal can
     * count "3/28" without the warmups inflating the total.
     *
     * @param  array<int, LoadStep>  $steps
     * @return array<int, array<string, mixed>>
     */
    protected function numbered(array $steps, HttpBenchCommand $command, bool $insecure): array
    {
        $done = 0;

        return array_values(array_map(function (LoadStep $step) use ($command, $insecure, &$done): array {
            if ($step->isMeasured()) {
                $done++;
            }

            return [
                'slot' => HttpBenchmarkResults::slotFor($step->route, $step->phase, $step->connections),
                'capture' => $step->isMeasured(),
                'done' => $done,
                'label_quoted' => escapeshellarg($step->label()),
                // 'oha' rather than a path: the generator runs whatever it has
                // on PATH, which is all the bootstrap ever asked it to install.
                'command' => $command->render($step, $insecure, 'oha', $this->connectTo),
            ];
        }, $steps));
    }

    /**
     * -k whenever either side of the conversation is https: the target is
     * often a self-signed loopback certificate, and the token — not the
     * transport — is what authenticates this exchange.
     *
     * @param  array<string, mixed>  $session
     */
    protected function curlInsecure(array $session): string
    {
        $https = str_starts_with($session['base_url'] ?? '', 'https://')
            || str_starts_with($session['target_url'] ?? '', 'https://');

        return $https ? '-k' : '';
    }
}
